<script setup lang="ts">
import { reactive,ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import AppPage from '../../components/AppPage.vue'
import Icon from '../../components/Icon.vue'
import { useHealthStore,newId } from '../../stores/health'
import { trainingTypes,feelings } from '../../domain/types'
import { dateKey } from '../../domain/dates'
import { back,confirm,numeric,toast } from '../../utils/ui'
const store=useHealthStore(),id=ref(''),error=ref('')
const form=reactive({date:dateKey(),type:'力量训练',minutes:'',feeling:'状态不错',note:''})
onLoad(q=>{if(q?.date)form.date=q.date;if(q?.id){const e=store.data.training.find(x=>x.id===q.id);if(!e){toast('这条记录已不存在');back();return}id.value=e.id;Object.assign(form,{...e,minutes:String(e.minutes)})}})
function save(){error.value='';try{const minutes=numeric(form.minutes,'训练时长',1,1440,true)!;if(!Number.isInteger(minutes))throw new Error('训练时长请填写整数分钟');if(store.saveTraining({id:id.value||newId(),date:form.date,type:form.type,minutes,feeling:form.feeling,note:form.note.trim()})){back();toast('训练已记录，辛苦了')}}catch(e){error.value=(e as Error).message}}
async function remove(){if(await confirm('删除这次训练？','删除后会同步更新本周训练次数与累计时长。')&&store.deleteTraining(id.value)){back();toast('记录已删除')}}
</script>
<template><AppPage :title="id?'编辑训练':'记录训练'"><text class="eyebrow">SHOW UP FOR YOURSELF</text><text class="page-title">为今天的努力留个记号</text><text class="page-description">不论强度，愿意开始就值得肯定。</text><view class="field mt-24"><text class="field-label">训练日期</text><picker mode="date" :value="form.date" :end="dateKey()" @change="form.date=$event.detail.value"><view class="input-wrap row-between"><view class="row gap-8"><Icon name="calendar" :size="18"/><text>{{ form.date }}</text></view><Icon name="arrow" tone="muted" :size="14"/></view></picker></view><view class="field"><text class="field-label">训练类型</text><view class="training-choices"><button role="button" v-for="type in trainingTypes" :key="type" class="choice" :class="{active:form.type===type}" @click="form.type=type">{{ type }}</button></view></view><view class="field"><text class="field-label">训练时长</text><view class="input-wrap duration-input"><Icon name="clock" :size="21"/><input aria-label="训练时长" v-model="form.minutes" type="number" placeholder="例如 45"/><text class="input-unit">分钟</text></view></view><view class="field"><text class="field-label">这次感觉怎么样？</text><view class="feeling-choices"><button role="button" v-for="feeling in feelings" :key="feeling" class="choice" :class="{active:form.feeling===feeling}" @click="form.feeling=feeling">{{ feeling }}</button></view></view><view class="field"><text class="field-label">给自己的一句话<text class="field-note">选填</text></text><view class="input-wrap"><textarea aria-label="训练备注" v-model="form.note" placeholder="例如：今天状态不错，记得好好拉伸。" maxlength="200" :auto-height="false"/></view><text class="helper note-count">{{ form.note.length }}/200</text></view><view class="notice"><Icon name="heart" :size="19"/><text>记录当下的感受，比和别人比较更重要。如果身体不舒服，给自己充分的休息。</text></view><text v-if="error" class="error-message">{{ error }}</text><view class="save-bar"><button role="button" class="btn-primary" @click="save"><Icon name="check" tone="white" :size="18"/>保存训练记录</button><button role="button" v-if="id" class="remove-record danger-link" @click="remove">删除这次训练</button></view></AppPage></template>
<style scoped>.training-choices{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.feeling-choices{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.duration-input{min-height:65px}.duration-input input{font-size:25px;font-weight:550;height:38px;margin-left:5px}.note-count{text-align:right;margin-top:7px}.remove-record{padding-top:18px;width:100%}</style>
